wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before reporting it as not accepted.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input this call received in the shared store.
        state_rw::put("last-input", &feed_url);

        // Clock: the time this heartbeat fired.
        let seconds = wall_clock::now().seconds;

        // HTTP: the one permitted fetch. A transport failure is a value, so a
        // down feed counts as zero characters rather than failing the heartbeat.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat to the digest channel. The contract
        // requires the notification to have been accepted, so retry a bounded
        // number of times. The reported value is always what the channel said.
        let message = format!(
            "heartbeat at {seconds}: fetched {fetched} characters from {feed_url}"
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
